# Issue #86 Phase 0 — focused test plan

These are the implementation gates before model execution and before any
evaluation code can be enabled. They are intentionally testable without model
downloads.

## Contract and isolation

- text and VL 768-D vectors reject cross-space comparison;
- representation IDs are stable for identical canonical inputs;
- changed rendition bytes or renderer revision creates a new identity;
- text and VL vectors cannot be written under one representation-space key;
- production defaults remain disabled and active production space is unchanged;
- sanitized manifests reject credentials, absolute production paths, and raw
  evidence payloads.

## Provenance and policy

- every representation inherits source/version/artifact, ACL, domain, system,
  component, environment, and evidence metadata;
- filtering occurs before dense retrieval, RRF, and reranker dispatch;
- reranking preserves candidate IDs and provenance exactly;
- QwenAgent receives only allow-listed provenance-aware tools;
- visual/document content cannot change workflow, limits, tools, or routing;
- image-only candidates are rejected by a text-only reranker rather than
  silently projected.

## Ingestion and idempotence

- text bundle commits when visual rendering fails;
- visual failure is retryable or quarantined with a bounded classification;
- unchanged rendition hash avoids duplicate object/DB work;
- re-ingestion is idempotent;
- page resolution, pixel count, image count, archive expansion, and batch size
  limits fail closed;
- malformed visual input cannot corrupt immutable originals or text chunks.

## Retrieval, reranking, and context

- RRF is deterministic under ties and never combines raw scores;
- candidate recall is recorded before reranking;
- reranker timeout/OOM/malformed output follows explicit fail-closed policy;
- source/page/region deduplication prevents representation crowding;
- context selection runs after reranking and enforces token/image/pixel/source
  budgets;
- retrieval events and result manifests identify first-stage, reranked, and
  context-retained phases.

## Planned execution order

1. Add pure contract/unit tests and sanitized manifest validation.
2. Add in-memory representation store and deterministic RRF tests.
3. Add bounded renderer/embedding failure tests using synthetic sanitized
   fixtures.
4. Run existing focused suite and complete suite.
5. Only after Phase 0 review, acquire models and run evaluation arms.

"""Model-independent qualification boundary for the pinned Qwen3 reranker.

This module deliberately does not acquire or execute weights.  A real adapter
may only be constructed after the artifact manifest is exact and executable.
"""

from __future__ import annotations

from dataclasses import dataclass
import math
from typing import Callable, Iterable, Sequence

from opennicf.evaluation import RerankerOutOfMemory, RerankerTimeout


MODEL_ID = "Qwen/Qwen3-Reranker-0.6B"
MODEL_REVISION = "e61197ed45024b0ed8a2d74b80b4d909f1255473"
MODEL_SHA256 = "27cd75a405b9c1b46b59abfd88aaa209e6fed2a1972cde9b70e7659537c5e65b"
MODEL_SIZE = 1_191_588_280
TOKENIZER_SHA256 = "aeb13307a71acd8fe81861d94ad54ab689df773318809eed3cbe794b4492dae4"
CONFIG_SHA256 = "d479c427a9ca5295218063d4f9aca4f297ab4ac27487cca7af42c84643d51ef0"
DEFAULT_INSTRUCTION = "Given a web search query, retrieve relevant passages that answer the query"
PREFIX = ('<|im_start|>system\nJudge whether the Document meets the requirements based on the Query and the '
          'Instruct provided. Note that the answer can only be "yes" or "no".<|im_end|>\n'
          '<|im_start|>user\n')
SUFFIX = "<|im_end|>\n<|im_start|>assistant\n<think>\n\n</think>\n\n"


def validate_artifact_manifest(manifest: dict[str, object]) -> tuple[str, ...]:
    """Fail closed unless the official identity and a concrete runtime are pinned."""
    expected = {
        "model": MODEL_ID, "revision": MODEL_REVISION, "license": "apache-2.0",
        "filename": "model.safetensors", "sha256": MODEL_SHA256, "size_bytes": MODEL_SIZE,
    }
    errors = [f"{key} does not match pinned artifact" for key, value in expected.items()
              if manifest.get(key) != value]
    for key in ("runtime", "runtime_version"):
        if not manifest.get(key):
            errors.append(f"{key} is required")
    for key, expected_hash in (("tokenizer_sha256", TOKENIZER_SHA256), ("config_sha256", CONFIG_SHA256)):
        if manifest.get(key) != expected_hash:
            errors.append(f"{key} does not match pinned artifact")
    if manifest.get("status") != "EXECUTABLE":
        errors.append("status must be EXECUTABLE")
    return tuple(errors)


def format_pair(query: str, document: str, instruction: str = DEFAULT_INSTRUCTION) -> str:
    return f"<Instruct>: {instruction}\n<Query>: {query}\n<Document>: {document}"


@dataclass(frozen=True)
class AdapterResult:
    scores: tuple[float, ...]
    ordered_indices: tuple[int, ...]
    truncated: tuple[bool, ...]


class DeterministicQwenRerankerAdapter:
    """Testable adapter using injected tokenization and final yes/no logits.

    The runner receives padded token batches and returns ``(no, yes)`` logits.
    This keeps timeout/OOM classification and prompt semantics testable without
    pretending a synthetic runner establishes model quality.
    """

    def __init__(self, encode: Callable[[str], list[int]],
                 runner: Callable[[Sequence[Sequence[int]], float], Sequence[tuple[float, float]]],
                 *, max_length: int = 8192, batch_size: int = 8, timeout_s: float = 30.0) -> None:
        if min(max_length, batch_size) <= 0 or timeout_s <= 0:
            raise ValueError("limits must be positive")
        self.encode, self.runner = encode, runner
        self.max_length, self.batch_size, self.timeout_s = max_length, batch_size, timeout_s

    def score(self, pairs: Iterable[tuple[str, str]], instruction: str = DEFAULT_INSTRUCTION) -> AdapterResult:
        prefix, suffix = self.encode(PREFIX), self.encode(SUFFIX)
        budget = self.max_length - len(prefix) - len(suffix)
        if budget < 1:
            raise ValueError("max_length cannot preserve prompt prefix and suffix")
        encoded, truncated = [], []
        for query, document in pairs:
            body = self.encode(format_pair(query, document, instruction))
            truncated.append(len(body) > budget)
            encoded.append(prefix + body[:budget] + suffix)
        scores: list[float] = []
        try:
            for start in range(0, len(encoded), self.batch_size):
                logits = self.runner(encoded[start:start + self.batch_size], self.timeout_s)
                if len(logits) != len(encoded[start:start + self.batch_size]):
                    raise ValueError("runner returned wrong score count")
                for no_logit, yes_logit in logits:
                    if not math.isfinite(no_logit) or not math.isfinite(yes_logit):
                        raise ValueError("runner returned nonfinite logits")
                    # Stable two-class softmax; higher means more relevant.
                    scores.append(1.0 / (1.0 + math.exp(max(-709.0, min(709.0, no_logit - yes_logit)))))
        except TimeoutError as error:
            raise RerankerTimeout("pinned Qwen reranker timed out") from error
        except MemoryError as error:
            raise RerankerOutOfMemory("pinned Qwen reranker exhausted memory") from error
        order = tuple(sorted(range(len(scores)), key=lambda index: (-scores[index], index)))
        return AdapterResult(tuple(scores), order, tuple(truncated))

"""Bounded, auditable administration of OpenNICF-owned knowledge data.

This module deliberately exposes metadata and lifecycle operations only.  It
does not grant access to evidence outside the caller's ACL/domain scope and
never deletes immutable source artifacts as part of retirement.
"""

from __future__ import annotations

import uuid
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass
from datetime import UTC, datetime
from typing import Any

from .embeddings import EmbeddingMigration, LocalFirstEmbeddingService
from .models import ParsedBlock, RetrievalFilters


def _now() -> datetime:
    return datetime.now(UTC)


@dataclass(frozen=True)
class RetirementPolicy:
    """Policy guard for a non-destructive source retirement."""

    allow_retirement: bool = True
    require_reason: bool = True
    preserve_provenance: bool = True
    legal_hold_metadata_key: str = "legal_hold"


@dataclass(frozen=True)
class AdminOperation:
    operation_id: str
    operation: str
    status: str
    requested_at: datetime
    actor: str
    target_id: str
    details: dict[str, Any]


class KnowledgeAdministration:
    """Small orchestration boundary for source and index administration.

    ``parser`` and ``reembed`` are injected because parsing and embedding are
    deployment-specific.  The service records an operation before invoking a
    callback, making retries and partial work visible without hiding failures.
    """

    def __init__(
        self,
        store: Any,
        *,
        object_store: Any | None = None,
        embeddings: LocalFirstEmbeddingService | None = None,
        parser: Callable[[bytes, str], Sequence[ParsedBlock]] | None = None,
    ):
        self.store = store
        self.object_store = object_store
        self.embeddings = embeddings
        self.parser = parser

    def list_sources(self, *, filters: RetrievalFilters | None = None, include_retired: bool = False) -> list[dict[str, Any]]:
        return self.store.list_sources(filters or RetrievalFilters(), include_retired=include_retired)

    def source_status(self, source_id: str, *, filters: RetrievalFilters | None = None) -> dict[str, Any]:
        status = self.store.source_status(source_id, filters=filters or RetrievalFilters())
        if self.object_store is not None:
            provenance = self.store.provenance(source_id, source_version_id=None, filters=filters or RetrievalFilters())
            versions = (provenance["version"],)
            status["object_present"] = all(self.object_store.exists(version["object_key"]) for version in versions)
        return status

    def provenance(self, source_id: str, *, source_version_id: str | None = None, filters: RetrievalFilters | None = None) -> dict[str, Any]:
        return self.store.provenance(source_id, source_version_id=source_version_id, filters=filters or RetrievalFilters())

    def retire_source(self, source_id: str, *, actor: str, reason: str, policy: RetirementPolicy | None = None) -> AdminOperation:
        policy = policy or RetirementPolicy()
        if not policy.allow_retirement:
            raise PermissionError("retirement is disabled by policy")
        if policy.require_reason and not reason.strip():
            raise ValueError("retirement reason is required")
        status = self.store.source_status(source_id, filters=RetrievalFilters())
        if status.get("metadata", {}).get(policy.legal_hold_metadata_key) is True:
            raise PermissionError("source is under legal hold")
        operation = self._start("retire", actor, source_id, {"reason": reason})
        try:
            self.store.retire_source(source_id, reason=reason, actor=actor, preserve_provenance=policy.preserve_provenance)
        except Exception as exc:  # noqa: BLE001 - persist operation failure state
            return self._finish(operation, "failed", {"error": str(exc)})
        return self._finish(operation, "complete", {"reason": reason})

    def retry_failed_ingestion(self, queue: Any, job_id: str, *, actor: str = "system") -> AdminOperation:
        operation = self._start("retry_ingestion", actor, job_id, {})
        try:
            retried = bool(queue.retry_dead_letter(job_id))
            if not retried:
                raise KeyError(f"dead-letter job not found: {job_id}")
        except Exception as exc:  # noqa: BLE001 - persist operation failure state
            return self._finish(operation, "failed", {"error": str(exc)})
        return self._finish(operation, "queued", {"job_id": job_id})

    def reparse(self, source_id: str, *, actor: str, parser: Callable[[bytes, str], Sequence[ParsedBlock]] | None = None, parser_version: str = "admin", ingest: Callable[..., Any] | None = None) -> AdminOperation:
        parser = parser or self.parser
        if parser is None or ingest is None:
            raise ValueError("reparse requires parser and ingest callbacks")
        provenance = self.store.provenance(source_id, filters=RetrievalFilters())
        operation = self._start("reparse", actor, source_id, {"parser_version": parser_version})
        try:
            version = provenance["version"]
            if self.object_store is None:
                raise RuntimeError("object store is required for reparse")
            content = self.object_store.get_bytes(version["object_key"])
            blocks = tuple(parser(content, version["source_uri"]))
            ingest(source_id=source_id, source_uri=version["source_uri"], content=content, blocks=blocks, parser_version=parser_version)
        except Exception as exc:  # noqa: BLE001 - persist operation failure state
            return self._finish(operation, "failed", {"error": str(exc)})
        return self._finish(operation, "complete", {"blocks": len(blocks), "source_version_id": version["source_version_id"]})

    def reindex(self, source_id: str, *, actor: str, reindex: Callable[[str], Any]) -> AdminOperation:
        return self._run_callback("reindex", source_id, actor, reindex)

    def reembed(self, chunks: Sequence[Any], *, actor: str, migration: EmbeddingMigration, privacy_policy: str = "cloud_allowed") -> AdminOperation:
        target = migration.target_space_id
        operation = self._start("reembed", actor, target, {"privacy_policy": privacy_policy, "count": len(chunks)})
        try:
            state = migration.run(chunks, self.store.save_embedding, privacy_policy=privacy_policy)
        except Exception as exc:  # noqa: BLE001 - persist operation failure state
            return self._finish(operation, "failed", {"error": str(exc), "embedding_space_id": target})
        return self._finish(operation, state.get("status", "paused"), {"embedding_space_id": target, **state})

    def embedding_space_status(self) -> dict[str, Any]:
        if self.embeddings is None:
            return {"spaces": [], "active_space_id": None, "migrations": {}}
        return {"spaces": self.embeddings.describe()["spaces"], "active_space_id": self.embeddings.active_space_id, "migrations": {key: dict(value) for key, value in self.embeddings.migration_state.items()}}

    def _start(self, operation: str, actor: str, target_id: str, details: Mapping[str, Any]) -> AdminOperation:
        record = AdminOperation(f"admin_{uuid.uuid4().hex}", operation, "running", _now(), actor, target_id, dict(details))
        self.store.record_admin_operation(record)
        return record

    def _finish(self, operation: AdminOperation, status: str, details: Mapping[str, Any]) -> AdminOperation:
        finished = AdminOperation(operation.operation_id, operation.operation, status, operation.requested_at, operation.actor, operation.target_id, {**operation.details, **dict(details), "finished_at": _now().isoformat()})
        self.store.record_admin_operation(finished)
        return finished

    def _run_callback(self, name: str, target_id: str, actor: str, callback: Callable[[str], Any]) -> AdminOperation:
        operation = self._start(name, actor, target_id, {})
        try:
            result = callback(target_id)
        except Exception as exc:  # noqa: BLE001 - persist operation failure state
            return self._finish(operation, "failed", {"error": str(exc)})
        return self._finish(operation, "complete", {"result": result} if isinstance(result, Mapping) else {})

