        started = self.clock()
        results: list[dict[str, Any]] = []
        for mode in MODES:
            applicable = [query for query in self.queries if mode in query.modes]
            for query in applicable:
                begin = self.clock()
                ranked = self._rank(mode, query)
                elapsed_ms = (self.clock() - begin) / 1_000_000
                compacted = compact_hits(ranked, max_chunks=self.max_context_chunks, max_tokens=self.max_context_tokens)
                query_metrics = _metrics(ranked, set(query.relevant_source_ids), k=self.k, latency_ms=elapsed_ms, compacted=compacted)
                results.append({
                    "mode": mode,
                    "query_id": query.query_id,
                    "query_hash": hashlib.sha256(query.text.encode()).hexdigest(),
                    "relevant_source_ids": list(query.relevant_source_ids),
                    "metrics": query_metrics,
                    "ranked": [
                        {
                            "rank": rank,
                            "chunk_id": hit.chunk_id,
                            "source_id": hit.source_id,
                            "source_version_id": hit.source_version_id,
                            "artifact_hash": hit.artifact_hash,
                            "locator": hit.locator,
                            "excerpt_hash": hit.excerpt_hash,
                            "score": round(hit.score, 8),
                            "embedding_space_id": hit.embedding_space_id,
                        }
                        for rank, hit in enumerate(ranked, 1)
                    ],
                    "compacted_chunk_ids": [hit.chunk_id for hit in compacted],
                })
        summaries: dict[str, Any] = {}
        for mode in MODES:
            mode_rows = [row for row in results if row["mode"] == mode]
            metric_rows = [row["metrics"] for row in mode_rows]
            summaries[mode] = {
                "query_count": len(mode_rows),
                "recall_at_k": round(mean(row["recall_at_k"] for row in metric_rows), 6) if metric_rows else 0.0,
                "mrr": round(mean(row["mrr"] for row in metric_rows), 6) if metric_rows else 0.0,
                "median_latency_ms": round(median(row["latency_ms"] for row in metric_rows), 3) if metric_rows else 0.0,
                "mean_returned_chunks": round(mean(row["returned_chunks"] for row in metric_rows), 3) if metric_rows else 0.0,
                "mean_context_tokens_after_compaction": round(mean(row["context_tokens_after_compaction"] for row in metric_rows), 3) if metric_rows else 0.0,
            }
        info = self.platform.embeddings.info(prefer_gpu=True)
        return {
            "benchmark_version": MANIFEST_VERSION,
            "fixture_manifest": self.manifest_path.name,
            "fixture_manifest_sha256": _manifest_hash(self.manifest),
            "fixture_set": self.manifest.get("fixture_set", "unknown"),
            "execution": {
                "knowledge_path": "KnowledgePlatform.in_memory",
                "fallback": bool(info.fallback),
                "fallback_reason": "deterministic_cpu_backend" if info.fallback else None,
                "embedding_space_id": self.platform.embeddings.active_space_id,
                "embedding_provider": info.provider,
                "embedding_model": info.model,
                "elapsed_ms": round((self.clock() - started) / 1_000_000, 3),
            },
            "metrics_definition": {
                "k": self.k,
                "recall_at_k": "fraction of queries with a relevant source in the first k chunks",
                "mrr": "mean reciprocal rank of the first relevant source",
                "latency_ms": "wall-clock retrieval duration per query; ranking is deterministic",
                "context_tokens_after_compaction": "Unicode word-token count after deduplication and bounded compaction",
            },
            "summaries": summaries,
            "results": results,
        }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", required=True, type=Path)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args(argv)
    platform = KnowledgePlatform.in_memory()
    report = RetrievalBenchmark(platform, args.manifest).run()
    rendered = json.dumps(report, indent=2, sort_keys=True) + "\n"
    if args.output:
        args.output.write_text(rendered, encoding="utf-8")
    else:
        print(rendered, end="")
    return 0


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())

"""QwenAgent adapter backed exclusively by :class:`ModelGateway`.

QwenAgent owns orchestration and tool loops; this adapter owns only the model
boundary.  Provider URLs, credentials, and routing policy stay in the gateway
and runtime environment.
"""
from __future__ import annotations

import os
from collections.abc import Iterator, Mapping
from typing import Any

from .model_gateway import ModelGateway, PrivacyPolicy


# QwenAgent may add framework-specific generation hints that are not part of
# the OpenAI-compatible provider contract.  Keep the provider payload narrow;
# in particular, clawproxy rejects QwenAgent's ``lang`` hint.
_PROVIDER_GENERATION_KEYS = frozenset(
    {
        "frequency_penalty",
        "max_tokens",
        "presence_penalty",
        "response_format",
        "seed",
        "stop",
        "temperature",
        "top_p",
        "tool_choice",
        "parallel_tool_calls",
    }
)


def _message_dict(message: Any) -> dict[str, Any]:
    if isinstance(message, Mapping):
        return dict(message)
    if hasattr(message, "model_dump"):
        return message.model_dump(exclude_none=True)
    return {
        key: getattr(message, key)
        for key in ("role", "content", "name", "function_call", "extra")
        if getattr(message, key, None) is not None
    }


class OpenNICFChatModel:
    """Minimal QwenAgent LLM protocol implemented through ``ModelGateway``.

    The class is deliberately duck-typed so importing OpenNICF does not make
    the optional qwen-agent dependency mandatory.  QwenAgent calls ``chat``;
    every request is converted into a gateway request and receives the same
    local-first, privacy, retry, and fallback policy as direct callers.
    """

    def __init__(
        self,
        gateway: ModelGateway | None = None,
        *,
        task_class: str | None = None,
        privacy: PrivacyPolicy | str | None = None,
        complex_input_chars: int = 12_000,
    ) -> None:
        self.gateway = gateway or ModelGateway.from_env()
        configured_provider = self.gateway.local_provider or self.gateway.remote_provider
        self.model = configured_provider.model if configured_provider else "opennicf-router"
        self.model_type = "opennicf_router"
        self.task_class = task_class or os.getenv("QWEN_TASK_CLASS", "simple_rag")
        configured_privacy = privacy or os.getenv("QWEN_PRIVACY", PrivacyPolicy.LOCAL_PREFERRED.value)
        self.privacy = PrivacyPolicy(configured_privacy)
        self.complex_input_chars = complex_input_chars

    @staticmethod
    def _messages(messages: list[Any]) -> list[dict[str, Any]]:
        return [_message_dict(message) for message in messages]

    def _request_options(self, messages: list[dict[str, Any]]) -> dict[str, Any]:
        size = sum(len(str(message.get("content", ""))) for message in messages)
        return {
            "task_class": self.task_class,
            "privacy": self.privacy,
            "complex_task": size >= self.complex_input_chars,
            "estimated_input_tokens": max(1, size // 4),
        }

    @staticmethod
    def _result_message(result: Any) -> Any:
        message: dict[str, Any] = {"role": "assistant", "content": result.content}
        if result.tool_calls:
            call = result.tool_calls[0]
            message["function_call"] = {"name": call.name, "arguments": call.arguments}
            message["extra"] = {"function_id": call.id}
        try:
            from qwen_agent.llm.schema import Message
        except ImportError:
            return message
        return Message(**message)

    @staticmethod
    def _content_message(content: str) -> Any:
        try:
            from qwen_agent.llm.schema import Message
        except ImportError:
            return {"role": "assistant", "content": content}
        return Message(role="assistant", content=content)

    def chat(
        self,
        messages: list[Any],
        functions: list[dict[str, Any]] | None = None,
        stream: bool = True,
        delta_stream: bool = False,
        extra_generate_cfg: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]] | Iterator[list[dict[str, Any]]]:
        normalized = self._messages(messages)
        options = self._request_options(normalized)
        extra_payload: dict[str, Any] = {}
        if functions:
            extra_payload["tools"] = functions
        if extra_generate_cfg:
            extra_payload.update(
                {
                    key: value
                    for key, value in extra_generate_cfg.items()
                    if key in _PROVIDER_GENERATION_KEYS
                }
            )

        if not stream:
            result = self.gateway.chat(
                normalized,
                **options,
                extra_payload=extra_payload,
            )
            return [self._result_message(result)]

        def stream_results() -> Iterator[list[dict[str, Any]]]:
            content = ""
            for chunk in self.gateway.stream_chat(
                normalized,
                **options,
                extra_payload=extra_payload,
            ):
                content += chunk.delta
                # QwenAgent's normal stream protocol expects the full message
                # accumulated so far when delta_stream is false.
                if delta_stream:
                    yield [self._content_message(chunk.delta)]
                else:
                    yield [self._content_message(content)]

        return stream_results()


__all__ = ["OpenNICFChatModel"]

"""Controlled deployment gates with deterministic promotion and rollback."""
from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass


@dataclass(frozen=True)
class GateResult:
    name: str
    passed: bool
    detail: str


@dataclass(frozen=True)
class DeploymentResult:
    release_id: str
    state: str
    gates: tuple[GateResult, ...]
    rolled_back_to: str | None = None


class DeploymentController:
    """The runner owns this state; GitHub CI only builds and verifies artifacts."""
    def __init__(self, *, known_good: str, deploy: Callable[[str], None], rollback: Callable[[str], None]) -> None:
        self.known_good = known_good
        self._deploy = deploy
        self._rollback = rollback

    def deploy_release(self, release_id: str, *, migration_gate: Callable[[], bool], health_gate: Callable[[], bool], smoke_gate: Callable[[], bool]) -> DeploymentResult:
        gates: list[GateResult] = []
        for name, gate in (("migration", migration_gate), ("health", health_gate), ("smoke", smoke_gate)):
            try:
                passed = bool(gate())
                detail = "passed" if passed else "failed"
            except Exception as exc:  # noqa: BLE001 - gate failures must trigger rollback
                passed, detail = False, f"failed: {type(exc).__name__}"
            gates.append(GateResult(name, passed, detail))
            if not passed:
                self._rollback(self.known_good)
                return DeploymentResult(release_id, "rolled_back", tuple(gates), self.known_good)
        try:
            self._deploy(release_id)
        except Exception as exc:  # noqa: BLE001 - deployment failures must trigger rollback
            gates.append(GateResult("deploy", False, f"failed: {type(exc).__name__}"))
            self._rollback(self.known_good)
            return DeploymentResult(release_id, "rolled_back", tuple(gates), self.known_good)
        self.known_good = release_id
        return DeploymentResult(release_id, "promoted", tuple(gates))

    def synthetic_deploy(self, release_id: str) -> DeploymentResult:
        return self.deploy_release(release_id, migration_gate=lambda: True, health_gate=lambda: True, smoke_gate=lambda: True)

"""Read-only contract preflight for the shared OpenAI-compatible endpoint."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import urllib.error
import urllib.request
from typing import Any


TEXT_MODEL = "text-embedding-qwen3-embedding-4b"
VL_MODEL = "qwen.qwen3-vl-embedding-2b"
ENDPOINT = "http://192.168.1.137:1234"


def request(base_url: str, path: str, *, payload: dict[str, Any] | None, token: str | None, timeout: float) -> tuple[int, dict[str, Any]]:
    headers = {"Accept": "application/json"}
    data = None
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        headers["Content-Type"] = "application/json"
    if token:
        headers["Authorization"] = f"Bearer {token}"
    req = urllib.request.Request(base_url.rstrip("/") + path, data=data, headers=headers, method="POST" if data else "GET")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            body = {"error_type": type(exc).__name__}
        return exc.code, body
    except (urllib.error.URLError, TimeoutError) as exc:
        return 0, {"error_type": type(exc).__name__}


def vector(result: dict[str, Any]) -> list[float]:
    data = result.get("data")
    if not isinstance(data, list) or len(data) != 1 or not isinstance(data[0], dict):
        raise ValueError("expected one embedding result")
    values = data[0].get("embedding")
    if not isinstance(values, list) or not values:
        raise ValueError("missing embedding vector")
    values = [float(value) for value in values]
    if not all(math.isfinite(value) for value in values):
        raise ValueError("non-finite embedding vector")
    if not any(value != 0.0 for value in values):
        raise ValueError("zero embedding vector")
    return values


def digest(values: list[float]) -> str:
    return hashlib.sha256(json.dumps(values, separators=(",", ":")).encode()).hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--base-url", default=os.environ.get("OPENNICF_EMBEDDING_BASE_URL", ENDPOINT))
    parser.add_argument("--service-token", default=os.environ.get("OPENNICF_EMBEDDING_SERVICE_TOKEN"))
    parser.add_argument("--timeout", type=float, default=30.0)
    args = parser.parse_args()
    report: dict[str, Any] = {
        "schema_version": 1,
        "endpoint": args.base_url,
        "text_model": TEXT_MODEL,
        "vl_model": VL_MODEL,
        "service_token_used": bool(args.service_token),
        "endpoint_ram": "UNVERIFIED",
        "production_enabled": False,
        "evaluation_vl_enabled": False,
    }

    status, models = request(args.base_url, "/v1/models", payload=None, token=args.service_token, timeout=args.timeout)
    advertised = [item.get("id") for item in models.get("data", []) if isinstance(item, dict)] if isinstance(models, dict) else []
    report["models"] = {"http_status": status, "advertised": advertised, "text_exact": TEXT_MODEL in advertised, "vl_exact": VL_MODEL in advertised}

    probes: dict[str, Any] = {}
    text_payload = {"model": TEXT_MODEL, "input": ["OpenNICF deterministic text probe"]}
    first_status, first = request(args.base_url, "/v1/embeddings", payload=text_payload, token=args.service_token, timeout=args.timeout)
    second_status, second = request(args.base_url, "/v1/embeddings", payload=text_payload, token=args.service_token, timeout=args.timeout)
    try:
        first_vector = vector(first)
        second_vector = vector(second)
        probes["text"] = {"http_status": first_status, "response_model": first.get("model"), "dimension": len(first_vector), "finite": True, "deterministic": first_vector == second_vector, "digest": digest(first_vector), "contract_pass": first.get("model") == TEXT_MODEL and len(first_vector) == 2560 and first_vector == second_vector}
    except (TypeError, ValueError) as exc:
        probes["text"] = {"http_status": first_status, "error": str(exc), "contract_pass": False}

    batch_status, batch = request(args.base_url, "/v1/embeddings", payload={"model": TEXT_MODEL, "input": ["probe A", "probe B"]}, token=args.service_token, timeout=args.timeout)
    probes["text_batch"] = {"http_status": batch_status, "count": len(batch.get("data", [])) if isinstance(batch, dict) and isinstance(batch.get("data"), list) else None, "ordered": [item.get("index") for item in batch.get("data", [])] == [0, 1] if isinstance(batch, dict) and isinstance(batch.get("data"), list) else False}

    invalid_status, invalid = request(args.base_url, "/v1/embeddings", payload={"model": "unconfigured-model", "input": ["probe"]}, token=args.service_token, timeout=args.timeout)
    report["invalid_model_rejected"] = invalid_status >= 400 or invalid.get("model") != "unconfigured-model"

    vl_status, vl = request(args.base_url, "/v1/embeddings", payload={"model": VL_MODEL, "input": ["OpenNICF VL identity probe"]}, token=args.service_token, timeout=args.timeout)
    vl_model = vl.get("model") if isinstance(vl, dict) else None
    probes["vl"] = {"http_status": vl_status, "response_model": vl_model, "status": "VL_UNVERIFIED" if vl_model == VL_MODEL else "VL_ALIASED_OR_UNSUPPORTED", "multimodal_probe": "NOT_RUN"}
    report["probes"] = probes
    report["vl_status"] = probes["vl"]["status"]
    report["text_endpoint_usable"] = bool(probes["text"].get("contract_pass"))
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Deterministic, explicitly non-human label generation for issue #86.

The functions consume copies of review artifacts and never mutate the source
queues.  Their output is comparative experimental evidence, not gold labels.
"""

from __future__ import annotations

from collections import Counter
from hashlib import sha256
import json
import re
from typing import Any, Iterable, Mapping


WARNING = [
    "AUTOMATED LABELS MAY CONTAIN SOURCE-DERIVED LEAKAGE",
    "QUALITY RESULTS ARE COMPARATIVE EXPERIMENTAL EVIDENCE",
    "PRODUCTION REMAINS UNCHANGED",
]
STATUSES = {"AUTO_ACCEPT", "AUTO_REWRITE", "AUTO_REJECT", "AUTO_HARD_NEGATIVE"}
LEAKAGE_STRATA = {"LOW_LEAKAGE", "MEDIUM_LEAKAGE", "HIGH_LEAKAGE", "EXACT_IDENTIFIER"}
TEXT_HARD_NEGATIVE_CATEGORIES = (
    "same_table_wrong_operation", "same_class_wrong_method", "same_service_wrong_endpoint",
    "same_error_wrong_service", "same_acronym_different_system", "same_document_wrong_section",
    "current_versus_obsolete", "production_versus_non_production",
    "same_identifier_wrong_semantic_context", "lexical_overlap_greater_than_relevant_evidence",
)


def _canonical(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()


def _digest(value: Any) -> str:
    return sha256(_canonical(value)).hexdigest()


def _tokens(value: str) -> set[str]:
    return set(re.findall(r"[\w.-]+", value.casefold()))


def _jaccard(left: str, right: str) -> float:
    a, b = _tokens(left), _tokens(right)
    return 0.0 if not (a or b) else round(len(a & b) / len(a | b), 6)


def _header(kind: str, source_sha256: str) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "manifest_kind": kind,
        "evaluation_mode": "AUTOMATED_NON_HUMAN_REVIEWED",
        "human_review_required_for_this_run": False,
        "decision_grade_production_validation": False,
        "production_migration_authorized": False,
        "recommendation_scope": "EXPERIMENTAL_ARCHITECTURE_ONLY",
        "automated_decisions_are_human_review": False,
        "production_decision": "NOT_AUTHORIZED",
        "production": "UNCHANGED",
        "deployments": 0,
        "merges": 0,
        "warnings": WARNING,
        "source_manifest_sha256": source_sha256,
    }


def _text_hn_category(item: Mapping[str, Any], ordinal: int) -> str:
    categories = set(item.get("categories", ()))
    path = str((item.get("intended_relevant") or [{}])[0].get("source_path", "")).casefold()
    if "EXACT_IDENTIFIER" in categories:
        return "same_identifier_wrong_semantic_context"
    if "SQL_DATABASE" in categories or path.endswith(".sql"):
        return "same_table_wrong_operation"
    if "CODE" in categories or path.endswith((".java", ".py", ".ps1")):
        return "same_class_wrong_method"
    if "LOG_INCIDENT" in categories or path.endswith(".log"):
        return "same_error_wrong_service"
    return TEXT_HARD_NEGATIVE_CATEGORIES[ordinal % len(TEXT_HARD_NEGATIVE_CATEGORIES)]


def build_text_automated_labels(review: Mapping[str, Any]) -> dict[str, Any]:
    """Convert the text review queue without applying or claiming human review."""
    items = sorted(
        (item for batch in review.get("batches", ()) for item in batch.get("items", ())),
        key=lambda row: row["query_id"],
    )
    rows: list[dict[str, Any]] = []
    for ordinal, item in enumerate(items):
        original = str(item.get("original_query_text") or item.get("query_text") or "").strip()
        relevant = [str(row["chunk_id"]) for row in item.get("intended_relevant", ()) if row.get("chunk_id")]
        relevant_text = "\n".join(str(row.get("text", "")) for row in item.get("intended_relevant", ()))
        relevant_text_keys = {" ".join(sorted(_tokens(str(row.get("text", ""))))) for row in item.get("intended_relevant", ())}
        candidates = [row for row in item.get("hard_negatives", ()) + item.get("hard_negative_candidates", ())
                      if row.get("chunk_id") and row.get("chunk_id") not in relevant
                      and " ".join(sorted(_tokens(str(row.get("text", ""))))) not in relevant_text_keys]
        candidate = candidates[0] if candidates else None
        invalid = not original or not relevant
        indicators = list(item.get("leakage_indicators", ()))
        exact = "EXACT_IDENTIFIER" in set(item.get("categories", ()))
        rewrite = str(item.get("rewrite_candidate") or "").strip()
        if invalid:
            status, automated, reason = "AUTO_REJECT", original, "missing intelligible query or valid relevant ID"
        elif "HARD_NEGATIVE" in set(item.get("categories", ())) and candidate:
            status = "AUTO_HARD_NEGATIVE"
            automated = rewrite if rewrite and rewrite != original else original
            reason = "explicit hard-negative query with a distinct deterministic candidate"
        elif indicators:
            status, automated = "AUTO_REWRITE", rewrite if rewrite and rewrite != original else f"Retrieve evidence that resolves: {original}"
            reason = "source-derived, duplicated, or answer-exposing phrasing"
        elif candidate:
            status, automated, reason = "AUTO_ACCEPT", original, "intelligible supported query with resolvable evidence"
        else:
            status, automated, reason = "AUTO_REJECT", original, "no meaningful hard-negative distractor available"
        leakage = "EXACT_IDENTIFIER" if exact else ("HIGH_LEAKAGE" if indicators else
                    ("MEDIUM_LEAKAGE" if _jaccard(original, relevant_text) >= 0.15 else "LOW_LEAKAGE"))
        negative = None if candidate is None else {
            "chunk_id": candidate["chunk_id"],
            "category": _text_hn_category(item, ordinal),
            "selection_method": "highest mechanical overlap, stable source order, excluding relevant IDs",
            "mechanical_overlap_score": candidate.get("mechanical_overlap_score"),
            "token_jaccard_similarity": _jaccard(automated, str(candidate.get("text", ""))),
            "source_path": candidate.get("source_path"),
        }
        row = {
            "query_id": item["query_id"], "automated_status": status, "leakage_stratum": leakage,
            "original_query_text": original, "automated_query_text": automated,
            "rewrite_reason": reason if automated != original else None,
            "original_relevant_ids": relevant, "final_relevant_ids": list(relevant),
            "label_identity_changed": False, "hard_negative": negative,
            "language": item.get("language"), "categories": list(item.get("categories", ())),
            "source_item_digest": item.get("item_digest"), "decision_rule_version": "issue86-auto-v1",
        }
        row["automated_decision_digest"] = _digest(row)
        rows.append(row)
    result = {**_header("AUTOMATED_TEXT_LABELS", _digest(review)), "labels": rows}
    result["counts"] = _counts(rows)
    result["labels_sha256"] = _digest(rows)
    return result


def build_multimodal_automated_labels(review: Mapping[str, Any]) -> dict[str, Any]:
    known = {row["representation_id"] for row in review.get("representations", ())}
    rows: list[dict[str, Any]] = []
    for item in sorted(review.get("queries", ()), key=lambda row: row["query_id"]):
        original = str(item.get("text", "")).strip()
        relevant = list(item.get("relevant_representation_ids", ()))
        negatives = [rid for rid in item.get("hard_negative_ids", ()) if rid not in relevant]
        unresolved = [rid for rid in (*relevant, *negatives) if rid not in known]
        indicators = list(item.get("leakage_indicators", ()))
        if not original or not relevant or unresolved:
            status, automated, reason = "AUTO_REJECT", original, "missing query/evidence or unresolved representation reference"
        elif not negatives:
            status, automated, reason = "AUTO_REJECT", original, "no meaningful multimodal hard negative"
        else:
            status = "AUTO_HARD_NEGATIVE"
            automated = (f"Locate the {str(item.get('category', 'visual')).replace('_', ' ')} evidence "
                         f"for {item.get('domain', 'the requested domain')}.") if indicators else original
            reason = "removed synthetic/source-derived identifying phrasing" if automated != original else "validated explicit visual distractor"
