class GeminiEmbeddingBackend:
    """Google AI Studio REST adapter; credentials are read only at call time."""

    def __init__(
        self,
        model: str,
        *,
        dimension: int = CANONICAL_DIMENSION,
        model_revision: str = "v1",
        api_key: str | None = None,
        transport: Callable[[str, dict[str, Any]], dict[str, Any]] | None = None,
    ):
        if model not in {"gemini-embedding-001", "gemini-embedding-2"}:
            raise ValueError("unsupported Gemini embedding model")
        self.model, self.dimension, self._api_key, self._transport = (
            model,
            dimension,
            api_key,
            transport,
        )
        self._info = EmbeddingModelInfo(
            model=model,
            dimensions=dimension,
            device="remote",
            backend="google-gemini",
            embedding_space_id=_space_id(model, dimension, model_revision),
            provider="GOOGLE",
            model_revision=model_revision,
        )

    @property
    def info(self) -> EmbeddingModelInfo:
        return self._info

    def _call(self, text: str, purpose: str) -> Sequence[float]:
        key = (
            self._api_key
            or os.environ.get("GOOGLE_API_KEY")
            or os.environ.get("GEMINI_API_KEY")
        )
        if not key and self._transport is None:
            raise EmbeddingError("Google embedding credentials are not configured")
        payload = {
            "model": self.model,
            "content": {"parts": [{"text": text}]},
            "output_dimensionality": self.dimension,
            "task_type": "RETRIEVAL_QUERY"
            if purpose == "retrieval_query"
            else "RETRIEVAL_DOCUMENT",
        }
        if self._transport:
            response = self._transport(self.model, payload)
        else:
            request = Request(
                f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:embedContent?key={key}",
                data=json.dumps(payload).encode(),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            try:
                with urlopen(request, timeout=30) as result:  # nosec B310 - fixed Google endpoint
                    response = json.loads(result.read().decode())
            except (HTTPError, URLError) as exc:
                raise EmbeddingError("Google embedding request failed") from exc
        values = response.get("embedding", {}).get("values") or response.get(
            "embeddings", [{}]
        )[0].get("values")
        if not values:
            raise EmbeddingError("Google embedding response did not contain values")
        return values

    def embed(
        self, texts: Sequence[str], *, purpose: str = "retrieval_document"
    ) -> EmbeddingResult:
        vectors = tuple(_normalize(self._call(text, purpose)) for text in texts)
        if any(len(vector) != self.dimension for vector in vectors):
            raise EmbeddingError("Google embedding returned the wrong dimensionality")
        return EmbeddingResult(
            model=self.model,
            dimensions=self.dimension,
            device="remote",
            vectors=vectors,
            embedding_space_id=self._info.embedding_space_id,
            provider="GOOGLE",
            model_revision=self._info.model_revision,
            normalized=True,
            purpose=purpose,
            metadata={"normalization": "verified_and_enforced", "task_type": purpose},
        )


class HttpEmbeddingBackend:
    """Provider-neutral client for the OpenNICF local embedding worker."""

    def __init__(
        self,
        base_url: str | None = None,
        *,
        service_token: str | None = None,
        timeout: float = 30.0,
        model: str = "Qwen/Qwen3-Embedding-0.6B",
        dimension: int = CANONICAL_DIMENSION,
        native_dimension: int | None = None,
        model_revision: str = "v1",
    ):
        self.base_url = (
            base_url or os.environ.get("OPENNICF_EMBEDDING_BASE_URL", "")
        ).rstrip("/")
        self.service_token = service_token or os.environ.get(
            "OPENNICF_EMBEDDING_SERVICE_TOKEN"
        )
        self.timeout = timeout
        self.dimension = dimension
        self.native_dimension = native_dimension or dimension
        if self.dimension <= 0 or self.native_dimension < self.dimension:
            raise ValueError("native embedding dimension must be >= output dimension")
        self._info = EmbeddingModelInfo(
            model=model,
            dimensions=dimension,
            device="remote-local",
            backend="opennicf-http",
            embedding_space_id=_space_id(model, dimension, model_revision),
            provider="LOCAL",
            model_revision=model_revision,
        )

    @property
    def info(self) -> EmbeddingModelInfo:
        return self._info

    def _request(
        self, path: str, payload: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        if not self.base_url:
            raise EmbeddingError("OPENNICF_EMBEDDING_BASE_URL is not configured")
        headers = {"Accept": "application/json"}
        if payload is not None:
            headers["Content-Type"] = "application/json"
        if self.service_token:
            headers["Authorization"] = f"Bearer {self.service_token}"
        request = Request(
            self.base_url + path,
            headers=headers,
            data=json.dumps(payload).encode() if payload is not None else None,
            method="POST" if payload is not None else "GET",
        )
        try:
            with urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode())
        except (HTTPError, URLError, TimeoutError, ValueError) as exc:
            raise EmbeddingError("local embedding service request failed") from exc

    def embed(
        self, texts: Sequence[str], *, purpose: str = "retrieval_document"
    ) -> EmbeddingResult:
        payload = self._request(
            "/v1/embeddings",
            {
                "model": self._info.model,
                "input": list(texts),
                "purpose": purpose,
                "dimension": self.dimension,
            },
        )
        response_model = payload.get("model")
        if response_model != self._info.model:
            raise EmbeddingError("local embedding service returned the wrong model")
        if payload.get("fallback", False):
            raise EmbeddingError(
                "local embedding service returned a CPU fallback for the configured space"
            )
        for response_dimension in (
            payload.get("dimension"),
            payload.get("dimensions"),
        ):
            if response_dimension is not None and response_dimension not in {
                self.dimension,
                self.native_dimension,
            }:
                raise EmbeddingError(
                    "local embedding service returned the wrong embedding dimension"
                )
        data = payload.get("data")
        if not isinstance(data, list) or len(data) != len(texts):
            raise EmbeddingError(
                "local embedding service returned the wrong result shape"
            )
        vectors: list[tuple[float, ...]] = []
        for index, item in enumerate(data):
            if not isinstance(item, dict) or item.get("index") != index:
                raise EmbeddingError(
                    "local embedding service returned the wrong result shape"
                )
            values = item.get("embedding")
            if not isinstance(values, (list, tuple)) or len(values) != self.native_dimension:
                raise EmbeddingError(
                    "local embedding service returned the wrong native embedding dimension"
                )
            try:
                # Keep the storage contract bounded at the configured output
                # dimension while retaining a distinct, versioned space ID.
                projected = tuple(float(value) for value in values[: self.dimension])
                if not all(isfinite(value) for value in projected):
                    raise ValueError("non-finite embedding value")
                norm = sqrt(sum(value * value for value in projected))
                if norm == 0:
                    raise ValueError("zero-norm embedding")
                vectors.append(tuple(value / norm for value in projected))
            except (TypeError, ValueError):
                raise EmbeddingError(
                    "local embedding service returned a non-finite or zero embedding"
                ) from None
        return EmbeddingResult(
            model=self._info.model,
            dimensions=self.dimension,
            device="remote-local",
            vectors=vectors,
            fallback=bool(payload.get("fallback", False)),
            metadata={
                "service": "opennicf-embedding-worker",
                "native_dimension": self.native_dimension,
                "projection": "first_n_values_then_l2_normalize"
                if self.native_dimension != self.dimension
                else "none",
            },
            embedding_space_id=self._info.embedding_space_id,
            provider="LOCAL",
            model_revision=self._info.model_revision,
            normalized=True,
            purpose=purpose,
        )


