def serve(service: KnowledgeService) -> ThreadingHTTPServer:
    server = ThreadingHTTPServer((service.config.host, service.config.port), KnowledgeRequestHandler)
    server.service = service
    return server

#!/usr/bin/env python3
"""Derive and evaluate Issue #86 reranked text arms from immutable scores."""
from __future__ import annotations

import argparse
from collections import Counter, defaultdict
from hashlib import sha256
import json
import math
from pathlib import Path
import random
import statistics


EXPECTED_PAIRS = 16_948
ARM_BASELINES = {"T02": "T00", "T03": "T01", "T06": "T04", "T07": "T05"}
DEPTHS = (5, 8, 10, 20, 30, 50)
METRIC_DEPTHS = (1, 3, 5, 8, 10)


def canonical(value: object) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()


def digest(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def stable_pair_id(query_id: str, chunk_id: str) -> str:
    return sha256(canonical([query_id, chunk_id])).hexdigest()


def load_scores(path: Path) -> tuple[dict, dict[tuple[str, str], dict]]:
    with path.open() as stream:
        manifest = json.loads(stream.readline())
        rows = [json.loads(line) for line in stream]
    if manifest.get("record_type") != "manifest" or manifest.get("expected_pairs") != EXPECTED_PAIRS:
        raise ValueError("score manifest contract mismatch")
    pairs: dict[tuple[str, str], dict] = {}
    pair_ids: set[str] = set()
    for row in rows:
        key = (row.get("query_id"), row.get("chunk_id"))
        if row.get("record_type") != "score" or key in pairs or row.get("pair_id") in pair_ids:
            raise ValueError("malformed or duplicate score record")
        if not isinstance(row.get("score"), (int, float)) or not math.isfinite(row["score"]) or not 0 <= row["score"] <= 1:
            raise ValueError("nonfinite score")
        if row.get("pair_id") != stable_pair_id(*key):
            raise ValueError("unstable pair ID")
        if row.get("ordered_input_sha256") != manifest.get("ordered_pairs_sha256"):
            raise ValueError("ordered input digest mismatch")
        if row.get("model_revision") != manifest.get("revision"):
            raise ValueError("model revision mismatch")
        if row.get("runtime") != manifest.get("runtime") or row.get("artifact_hashes") != manifest.get("artifact_hashes"):
            raise ValueError("runtime or artifact provenance mismatch")
        pairs[key] = row
        pair_ids.add(row["pair_id"])
    if len(rows) != EXPECTED_PAIRS or len(pairs) != EXPECTED_PAIRS:
        raise ValueError(f"score coverage mismatch: {len(rows)}/{len(pairs)}")
    return manifest, pairs


def rerank(first_stage: list[str], query_id: str, scores: dict[tuple[str, str], dict], depth: int) -> list[str]:
    candidates = first_stage[:depth]
    if len(candidates) != len(set(candidates)):
        raise ValueError(f"duplicate first-stage candidate for {query_id}")
    missing = [chunk_id for chunk_id in candidates if (query_id, chunk_id) not in scores]
    if missing:
        raise ValueError(f"missing reranker score for {query_id}: {missing[0]}")
    original = {chunk_id: index for index, chunk_id in enumerate(candidates)}
    ordered = sorted(candidates, key=lambda chunk_id: (-scores[(query_id, chunk_id)]["score"], original[chunk_id], chunk_id))
    return ordered + first_stage[depth:]


def query_metrics(ranking: list[str], relevant_ids: list[str], negative_id: str | None) -> dict[str, float]:
    relevant = set(relevant_ids)
    if not relevant:
        raise ValueError("query has no relevant IDs")
    output: dict[str, float] = {}
    for depth in METRIC_DEPTHS:
        selected = ranking[:depth]
        output[f"recall_at_{depth}"] = len(relevant.intersection(selected)) / len(relevant)
        output[f"precision_at_{depth}"] = len(relevant.intersection(selected)) / depth
    for depth in (5, 10):
        first = next((rank for rank, item in enumerate(ranking[:depth], 1) if item in relevant), None)
        output[f"mrr_at_{depth}"] = 0.0 if first is None else 1.0 / first
        dcg = sum(1.0 / math.log2(rank + 1) for rank, item in enumerate(ranking[:depth], 1) if item in relevant)
        idcg = sum(1.0 / math.log2(rank + 1) for rank in range(1, min(depth, len(relevant)) + 1))
        output[f"ndcg_at_{depth}"] = dcg / idcg
    output["query_coverage"] = float(bool(ranking))
    output["zero_hit_rate"] = float(not relevant.intersection(ranking[:10]))
    for depth in (1, 3, 5):
        output[f"hard_negative_fp_at_{depth}"] = float(bool(negative_id and negative_id in ranking[:depth]))
    return output


def aggregate(per_query: dict[str, dict[str, float]], query_ids: list[str]) -> dict:
    if not query_ids:
        return {"query_count": 0, "metrics": {}}
    keys = sorted(next(iter(per_query.values())))
    return {"query_count": len(query_ids), "metrics": {
        key: sum(per_query[qid][key] for qid in query_ids) / len(query_ids) for key in keys
    }}


def bootstrap(baseline: dict[str, float], candidate: dict[str, float], samples: int = 2000, seed: int = 86) -> dict:
    if set(baseline) != set(candidate) or not baseline:
        raise ValueError("paired bootstrap inputs differ")
    deltas = [candidate[qid] - baseline[qid] for qid in sorted(baseline)]
    rng = random.Random(seed)
    means = sorted(sum(rng.choice(deltas) for _ in deltas) / len(deltas) for _ in range(samples))
    return {"mean_delta": statistics.fmean(deltas), "ci95_low": means[int(samples * .025)],
            "ci95_high": means[min(samples - 1, int(samples * .975))], "query_count": len(deltas),
            "samples": samples, "seed": seed,
            "interpretation": "SUPPORTED" if means[int(samples * .025)] > 0 or means[min(samples - 1, int(samples * .975))] < 0 else "INCONCLUSIVE"}


def percentile(values: list[float], quantile: float) -> float:
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, math.ceil(quantile * len(ordered)) - 1)]


def reconstruct_batch_telemetry(rows: list[dict]) -> dict:
    """Use one repeated batch latency per contiguous emitted batch."""
    batches: list[tuple[int, float]] = []
    index = 0
    while index < len(rows):
        size = int(rows[index]["effective_batch_size"])
        selected = rows[index:index + size]
        latency = float(rows[index]["batch_elapsed_seconds"])
        if len(selected) != size or any(int(row["effective_batch_size"]) != size or
                                        float(row["batch_elapsed_seconds"]) != latency for row in selected):
            raise ValueError(f"cannot reconstruct emitted batch at record {index}")
        batches.append((size, latency))
        index += size
    output = {}
    for size in (1, 2, 4):
        latencies = [latency for batch_size, latency in batches if batch_size == size]
        output[str(size)] = {"batch_count": len(latencies), "pair_count": len(latencies) * size,
                             "pairs_per_second_service_time": (len(latencies) * size / sum(latencies)) if latencies else None,
                             "batch_latency_seconds_p50": percentile(latencies, .50) if latencies else None,
                             "batch_latency_seconds_p95": percentile(latencies, .95) if latencies else None,
                             "batch_latency_seconds_p99": percentile(latencies, .99) if latencies else None}
    return {"by_effective_batch_size": output, "batch_count": len(batches),
            "limitations": "GPU service-time reconstruction only; resumed run_elapsed values do not provide wall-clock queue/request latency or concurrency telemetry."}


def strata_for(labels: list[dict]) -> dict[str, list[str]]:
    strata: dict[str, list[str]] = defaultdict(list)
    for item in labels:
        qid = item["query_id"]
        strata[item["leakage_stratum"]].append(qid)
        for category in item.get("categories", []):
            strata[category].append(qid)
        if item.get("hard_negative"):
            strata["EXPLICIT_HARD_NEGATIVE"].append(qid)
        language = item.get("language")
        if language:
            strata[language].append(qid)
    return {key: sorted(set(value)) for key, value in sorted(strata.items())}


def rag_metrics(ranking: list[str], label: dict, chunks: dict[str, dict], depth: int) -> dict:
    context = ranking[:depth]
    relevant = set(label["final_relevant_ids"])
    negative = label.get("hard_negative", {}).get("chunk_id")
    sources = [chunks[item]["source_id"] for item in context]
    tokens = sum(len(chunks[item]["text"].split()) for item in context)
    hits = len(relevant.intersection(context))
    return {"context_recall": hits / len(relevant), "context_precision": hits / depth,
            "answerable_with_context": float(hits > 0), "relevant_evidence_retained": float(hits > 0),
            "explicit_hard_negative_present": float(bool(negative and negative in context)),
            "duplicate_evidence_rate": 1 - len(set(context)) / len(context),
            "source_diversity": len(set(sources)) / len(sources), "context_token_estimate": tokens,
            "context_token_utilization_vs_8192_estimate": min(tokens / 8192, 1.0)}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--report", type=Path, required=True)
    parser.add_argument("--scores", type=Path, required=True)
    parser.add_argument("--labels", type=Path, required=True)
    parser.add_argument("--corpus", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--rag-output", type=Path, required=True)
    args = parser.parse_args()
    report = json.loads(args.report.read_text())
    labels_doc = json.loads(args.labels.read_text())
    corpus = json.loads(args.corpus.read_text())
    manifest, scores = load_scores(args.scores)
    labels = labels_doc["labels"]
    label_map = {item["query_id"]: item for item in labels}
    query_ids = sorted(label_map)
    chunks = {item["chunk_id"]: item for item in corpus["chunks"]}
    if set(query_ids) != set(next(iter(report["arms"].values()))["rankings"]):
        raise ValueError("query coverage mismatch")
    expected_keys = {(qid, chunk_id) for arm in ("T00", "T01", "T04", "T05")
                     for qid, ranking in report["arms"][arm]["rankings"].items() for chunk_id in ranking}
    if expected_keys != set(scores):
        raise ValueError("complete query/candidate score coverage mismatch")

    rankings_by_depth: dict[str, dict[str, dict[str, list[str]]]] = {}
    rankings: dict[str, dict[str, list[str]]] = {arm: report["arms"][arm]["rankings"] for arm in ("T00", "T01", "T04", "T05")}
    for arm, baseline in ARM_BASELINES.items():
        rankings_by_depth[arm] = {}
        for depth in DEPTHS:
            rankings_by_depth[arm][str(depth)] = {
                qid: rerank(rankings[baseline][qid], qid, scores, depth) for qid in query_ids
            }
        rankings[arm] = rankings_by_depth[arm]["50"]

    per_arm = {}
    strata = strata_for(labels)
    arms = {}
    for arm in sorted(rankings):
        per = {qid: query_metrics(rankings[arm][qid], label_map[qid]["final_relevant_ids"],
                                  label_map[qid].get("hard_negative", {}).get("chunk_id")) for qid in query_ids}
        per_arm[arm] = per
        arms[arm] = {"status": "EXECUTED", "baseline": ARM_BASELINES.get(arm),
                     "metrics": {"OVERALL": aggregate(per, query_ids), **{name: aggregate(per, ids) for name, ids in strata.items()}},
                     "rankings": rankings[arm]}

    comparisons = {}
    for candidate, baseline in ARM_BASELINES.items():
        key = f"{candidate}_minus_{baseline}"
        comparisons[key] = {}
        for metric in ("recall_at_5", "recall_at_10", "mrr_at_5", "mrr_at_10", "ndcg_at_5", "ndcg_at_10", "hard_negative_fp_at_1", "hard_negative_fp_at_5"):
            comparisons[key][metric] = bootstrap({q: per_arm[baseline][q][metric] for q in query_ids},
                                                  {q: per_arm[candidate][q][metric] for q in query_ids})

    depth_analysis = {}
    depth_paired_bootstrap = {}
    disagreements = {}
    for arm, baseline in ARM_BASELINES.items():
        depth_analysis[arm] = {}
        depth_per_all = {}
        for depth in DEPTHS:
            depth_per = {qid: query_metrics(rankings_by_depth[arm][str(depth)][qid], label_map[qid]["final_relevant_ids"],
                                             label_map[qid].get("hard_negative", {}).get("chunk_id")) for qid in query_ids}
            depth_per_all[depth] = depth_per
            depth_analysis[arm][str(depth)] = aggregate(depth_per, query_ids)
        depth_paired_bootstrap[arm] = {}
        for depth in DEPTHS[:-1]:
            depth_paired_bootstrap[arm][f"{depth}_minus_50"] = {
                metric: bootstrap({q: depth_per_all[50][q][metric] for q in query_ids},
                                  {q: depth_per_all[depth][q][metric] for q in query_ids})
                for metric in ("recall_at_5", "recall_at_10", "mrr_at_10", "ndcg_at_10")
            }
        rows = []
        counts = Counter()
        for qid in query_ids:
            relevant = set(label_map[qid]["final_relevant_ids"])
            left = next((i for i, x in enumerate(rankings[baseline][qid][:10], 1) if x in relevant), None)
            right = next((i for i, x in enumerate(rankings[arm][qid][:10], 1) if x in relevant), None)
            outcome = "tie" if left == right else "win" if right is not None and (left is None or right < left) else "loss"
            counts[outcome] += 1
            rows.append({"query_id": qid, "baseline_rank": left, "reranked_rank": right, "outcome": outcome,
                         "rank_displacement": None if left is None or right is None else left - right,
                         "leakage_stratum": label_map[qid]["leakage_stratum"], "categories": label_map[qid].get("categories", [])})
        disagreements[arm] = {"counts": dict(sorted(counts.items())), "queries": rows}

    score_rows = list(scores.values())
    result = {"schema_version": 1, "evaluation_mode": "AUTOMATED_NON_HUMAN_REVIEWED",
              "decision_grade_production_validation": False, "canonical_arm_mapping": ARM_BASELINES,
              "arm_mapping_resolution": "Preserved repository and immutable-score canonical IDs: T02=T00+r, T03=T01+r, T06=T04+r, T07=T05+r; the latest phase prose transposed T03 and T06 descriptions.",
              "score_integrity": {"expected_pairs": EXPECTED_PAIRS, "completed_pairs": len(scores), "duplicates": 0,
                                  "missing": 0, "nonfinite": 0, "score_file_sha256": digest(args.scores),
                                  "ordered_pairs_sha256": manifest["ordered_pairs_sha256"], "manifest": manifest,
                                  "oom_retries": max(row["oom_count"] for row in score_rows),
                                  "batch_distribution": dict(sorted(Counter(str(row["effective_batch_size"]) for row in score_rows).items()))},
              "scoring_telemetry": reconstruct_batch_telemetry(score_rows),
              "source_digests": {"report_sha256": digest(args.report), "labels_sha256": digest(args.labels), "corpus_sha256": digest(args.corpus)},
              "arms": arms, "paired_bootstrap": comparisons, "depth_analysis": depth_analysis,
              "depth_paired_bootstrap": depth_paired_bootstrap,
              "disagreement_analysis": disagreements, "production_decision": "NOT_AUTHORIZED",
              "production": "UNCHANGED", "deployments": 0, "merges": 0}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_bytes(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True).encode() + b"\n")

    rag_arms = {}
    for arm in sorted(rankings):
        rag_arms[arm] = {}
        for depth in (5, 8, 10):
            per = {qid: rag_metrics(rankings[arm][qid], label_map[qid], chunks, depth) for qid in query_ids}
            rag_arms[arm][str(depth)] = aggregate(per, query_ids)
    rag = {"evaluation_mode": "AUTOMATED_NON_HUMAN_REVIEWED", "decision_grade_production_validation": False,
           "result_kind": "RETRIEVAL_ONLY_RAG_PRECHECK_NOT_GENERATED_ANSWERS", "generator_used": False,
           "judge_used": False, "generated_answer_metrics": "NOT_EXECUTED_NO_PINNED_GENERATOR_JUDGE_CONTRACT",
           "source_text_report_sha256": sha256(args.output.read_bytes()).hexdigest(), "arms": rag_arms,
           "production_decision": "NOT_AUTHORIZED", "production": "UNCHANGED", "deployments": 0, "merges": 0}
    args.rag_output.write_bytes(json.dumps(rag, ensure_ascii=False, indent=2, sort_keys=True).encode() + b"\n")


if __name__ == "__main__":
    main()

"""Model-free contracts for the issue #86 evaluation.

This module is deliberately evaluation-only. It does not select a provider,
write production persistence, or execute a model. It makes rendition identity,
space identity, and manifest safety rules executable before model acquisition.
"""
from __future__ import annotations

import hashlib
import json
import re
from dataclasses import dataclass, field
from typing import Any


REPRESENTATION_TYPES = {"text", "page_image", "region_image", "mixed"}
REPRESENTATION_LIFECYCLE = {"pending", "ready", "failed", "quarantined", "retired"}
MANIFEST_STATES = {"DRAFT", "EXECUTABLE"}
FAILURE_POLICIES = {"FAIL_QUERY", "FALLBACK_TO_FUSED_ORDER", "SKIP_UNSUPPORTED_CANDIDATE"}
HEX64 = re.compile(r"^[0-9a-f]{64}$")
PLACEHOLDER = re.compile(r"^(?:exact |recorded |path/to/|TODO|placeholder)", re.I)


class ManifestValidationError(ValueError):
    """Raised when an issue #86 manifest cannot be safely executed."""


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def stable_representation_id(
    *,
    source_version_id: str,
    representation_type: str,
    locator: str,
    parent_chunk_id: str | None,
    rendition_hash: str,
    render_name: str,
    render_version: str,
) -> str:
    """Return a rendition identity independent of embedding space/model."""
    if representation_type not in REPRESENTATION_TYPES:
        raise ValueError(f"unsupported representation_type: {representation_type}")
    canonical = {
        "source_version_id": source_version_id,
        "representation_type": representation_type,
        "locator": locator,
        "parent_chunk_id": parent_chunk_id,
        "rendition_hash": rendition_hash,
        "render_name": render_name,
        "render_version": render_version,
    }
    return "rep_" + hashlib.sha256(_canonical(canonical).encode()).hexdigest()


@dataclass(frozen=True)
class RepresentationRecord:
    representation_id: str
    source_id: str
    source_version_id: str
    artifact_hash: str
    representation_type: str
    locator: str
    parent_chunk_id: str | None
    object_key: str | None
    mime_type: str
    rendition_hash: str
    render_name: str
    render_version: str
    lifecycle_status: str = "ready"
    failure_classification: str | None = None
    attempt_count: int = 0
    metadata: dict[str, Any] = field(default_factory=dict)
    pixel_width: int | None = None
    pixel_height: int | None = None
    acl_scope: str = ""
    domain_id: str = ""
    system_id: str = ""
    component_id: str = "unknown-component"
    environment: str = ""
    evidence_type: str = ""


@dataclass(frozen=True)
class EmbeddingVariant:
    representation_id: str
    embedding_space_id: str
    model: str
    model_revision: str
    quantization: str
    native_dimensions: int
    dimensions: int
    normalized: bool
    vector: tuple[float, ...] = ()


def compare_embeddings(left: EmbeddingVariant, right: EmbeddingVariant) -> float:
    """Compare only vectors from the same semantic space."""
    if left.embedding_space_id != right.embedding_space_id:
        raise ValueError("embedding-space mismatch: vectors cannot be compared")
    if len(left.vector) != len(right.vector):
        raise ValueError("embedding dimensions do not match")
    return sum(a * b for a, b in zip(left.vector, right.vector))


class InMemoryRepresentationStore:
    """Idempotent isolated contract store used by model-free tests."""

    def __init__(self) -> None:
        self.representations: dict[str, RepresentationRecord] = {}
        self.embeddings: dict[tuple[str, str], EmbeddingVariant] = {}

    def put_representation(self, record: RepresentationRecord) -> RepresentationRecord:
        if record.representation_type not in REPRESENTATION_TYPES:
            raise ValueError(f"unsupported representation_type: {record.representation_type}")
        if record.lifecycle_status not in REPRESENTATION_LIFECYCLE:
            raise ValueError(f"unsupported lifecycle_status: {record.lifecycle_status}")
        if record.attempt_count < 0:
            raise ValueError("attempt_count must be non-negative")
        if record.representation_type != "text" and not record.object_key:
            raise ValueError("non-text representations require an object_key")
        for name, value in (("pixel_width", record.pixel_width), ("pixel_height", record.pixel_height)):
            if value is not None and value <= 0:
                raise ValueError(f"{name} must be positive when provided")
        expected = stable_representation_id(
            source_version_id=record.source_version_id,
            representation_type=record.representation_type,
            locator=record.locator,
            parent_chunk_id=record.parent_chunk_id,
            rendition_hash=record.rendition_hash,
            render_name=record.render_name,
            render_version=record.render_version,
        )
        if record.representation_id != expected:
            raise ValueError("representation_id does not match canonical rendition identity")
        existing = self.representations.get(record.representation_id)
        if existing is not None and existing != record:
            raise ValueError("representation identity collision with different rendition metadata")
        self.representations[record.representation_id] = record
        return record

    def put_embedding(self, variant: EmbeddingVariant) -> EmbeddingVariant:
        if variant.representation_id not in self.representations:
            raise KeyError("embedding requires an existing representation")
        if variant.dimensions <= 0 or variant.native_dimensions <= 0:
            raise ValueError("embedding dimensions must be positive")
        key = (variant.representation_id, variant.embedding_space_id)
        existing = self.embeddings.get(key)
        if existing is not None and existing != variant:
            raise ValueError("embedding-space identity collision")
        self.embeddings[key] = variant
        return variant

    def get_representation(self, representation_id: str) -> RepresentationRecord | None:
        return self.representations.get(representation_id)

    def get_embedding(self, representation_id: str, embedding_space_id: str) -> EmbeddingVariant | None:
        return self.embeddings.get((representation_id, embedding_space_id))

    def list_representations(self, *, lifecycle_status: str | None = None) -> tuple[RepresentationRecord, ...]:
        records = self.representations.values()
        if lifecycle_status is not None:
            if lifecycle_status not in REPRESENTATION_LIFECYCLE:
                raise ValueError(f"unsupported lifecycle_status: {lifecycle_status}")
            records = (record for record in records if record.lifecycle_status == lifecycle_status)
        return tuple(sorted(records, key=lambda record: record.representation_id))

    def eligible_representations(
        self,
        embedding_space_id: str,
        *,
        acl_scopes: frozenset[str] = frozenset(),
        domain_ids: frozenset[str] = frozenset(),
        system_ids: frozenset[str] = frozenset(),
    ) -> tuple[RepresentationRecord, ...]:
        """Return ready, embedded renditions authorized by explicit policy filters."""
        return tuple(
            record
            for record in self.list_representations(lifecycle_status="ready")
            if (record.representation_id, embedding_space_id) in self.embeddings
            and (not acl_scopes or record.acl_scope in acl_scopes)
            and (not domain_ids or record.domain_id in domain_ids)
            and (not system_ids or record.system_id in system_ids)
        )


def rrf_rank(
    ranked_lanes: list[list[str]],
    *,
    k_rrf: int = 60,
) -> list[str]:
    """Fuse ranked candidate IDs without comparing raw lane scores."""
    if k_rrf <= 0:
        raise ValueError("k_rrf must be positive")
    scores: dict[str, float] = {}
    first_rank: dict[str, int] = {}
    for lane in ranked_lanes:
        seen_in_lane: set[str] = set()
        for rank, candidate_id in enumerate(lane, 1):
            # A repeated representation is one candidate in a lane.  Keep its
            # first (best) rank and do not let a later occurrence contribute a
            # second reciprocal-rank term.
            if candidate_id in seen_in_lane:
                continue
            seen_in_lane.add(candidate_id)
            scores[candidate_id] = scores.get(candidate_id, 0.0) + 1.0 / (k_rrf + rank)
            first_rank[candidate_id] = min(first_rank.get(candidate_id, rank), rank)
    return sorted(scores, key=lambda candidate_id: (-scores[candidate_id], first_rank[candidate_id], candidate_id))


def _fail(errors: list[str], condition: bool, message: str) -> None:
    if condition:
        errors.append(message)


def validate_manifest(manifest: dict[str, Any], *, execution: bool = False) -> None:
    """Validate a sanitized issue #86 manifest; fail closed on every violation."""
    errors: list[str] = []
    state = manifest.get("state")
    _fail(errors, state not in MANIFEST_STATES, "state must be DRAFT or EXECUTABLE")
    _fail(errors, manifest.get("production") is not False, "production must be false")
    _fail(errors, manifest.get("production_migration_authorized") is not False, "production migration must be unauthorized")
    _fail(errors, execution and state != "EXECUTABLE", "DRAFT manifests cannot execute")
    if state == "EXECUTABLE":
        required = ("corpus_manifest_digest", "reviewed_label_digest", "runtime_digest")
        _fail(errors, any(not manifest.get(key) or PLACEHOLDER.search(str(manifest[key])) for key in required), "EXECUTABLE manifest requires resolved corpus, label, and runtime digests")

    spaces = manifest.get("spaces", [])
    if isinstance(spaces, dict):
        spaces = list(spaces.values())
    space_ids: set[str] = set()
    for space in spaces:
        sid = space.get("id")
        _fail(errors, not sid or sid in space_ids, "space IDs must be present and unique")
        if sid:
            space_ids.add(sid)
        for key in ("model", "model_revision", "artifact_sha256", "runtime", "quantization", "native_dimensions", "dimensions", "normalized", "preprocessing", "modality"):
            value = space.get(key)
            _fail(errors, value in (None, "") or (state == "EXECUTABLE" and PLACEHOLDER.search(str(value)) is not None), f"space {sid or '<unknown>'} missing resolved {key}")
        _fail(errors, not isinstance(space.get("dimensions"), int) or space.get("dimensions", 0) <= 0, f"space {sid or '<unknown>'} has invalid dimensions")
        _fail(errors, not isinstance(space.get("native_dimensions"), int) or space.get("native_dimensions", 0) <= 0, f"space {sid or '<unknown>'} has invalid native dimensions")
        _fail(errors, not isinstance(space.get("normalized"), bool), f"space {sid or '<unknown>'} must declare normalization")
        artifact = str(space.get("artifact_sha256", ""))
        _fail(errors, state == "EXECUTABLE" and not HEX64.fullmatch(artifact), f"space {sid or '<unknown>'} has invalid artifact SHA-256")
    modalities = {str(x.get("modality")) for x in spaces}
    _fail(errors, len(space_ids) != len(spaces), "duplicate space IDs")
    _fail(errors, len([x for x in spaces if x.get("modality") == "text"]) > 1 and len({x.get("id") for x in spaces if x.get("modality") == "text"}) != len([x for x in spaces if x.get("modality") == "text"]), "duplicate text spaces")
    for representation_type in manifest.get("representation_types", ["text"]):
        _fail(errors, representation_type not in REPRESENTATION_TYPES, f"unknown representation type: {representation_type}")

    rerankers = manifest.get("rerankers", [])
    if isinstance(rerankers, dict):
        rerankers = list(rerankers.values())
    reranker_ids: set[str] = set()
    for reranker in rerankers:
        rid = reranker.get("id")
        _fail(errors, not rid or rid in reranker_ids, "reranker IDs must be present and unique")
        if rid:
            reranker_ids.add(rid)
        for key in ("model", "model_revision", "artifact_sha256", "runtime", "quantization", "capabilities", "failure_policy"):
            value = reranker.get(key)
            _fail(errors, value in (None, "") or (state == "EXECUTABLE" and PLACEHOLDER.search(str(value)) is not None), f"reranker {rid or '<unknown>'} missing resolved {key}")
        _fail(errors, reranker.get("failure_policy") not in FAILURE_POLICIES, f"reranker {rid or '<unknown>'} has invalid failure policy")
        _fail(errors, state == "EXECUTABLE" and not HEX64.fullmatch(str(reranker.get("artifact_sha256", ""))), f"reranker {rid or '<unknown>'} has invalid artifact SHA-256")

    fusion = manifest.get("fusion", {})
    _fail(errors, not isinstance(fusion, dict) or fusion.get("method") != "rrf", "fusion must use RRF")
    if isinstance(fusion, dict):
        _fail(errors, not isinstance(fusion.get("k_rrf"), int) or fusion.get("k_rrf", 0) <= 0, "k_rrf must be a positive integer")
        _fail(errors, fusion.get("raw_score_fusion") is True, "raw-score fusion is forbidden")

    depths = manifest.get("candidate_depths", [])
    _fail(errors, not depths or any(not isinstance(x, int) or x < 1 or x > 50 for x in depths), "candidate depths must be integers in 1..50")
    arms = manifest.get("arms", [])
    arm_ids: set[str] = set()
    for arm in arms:
        aid = arm.get("id")
        _fail(errors, not aid or aid in arm_ids, "arm IDs must be present and unique")
        if aid:
            arm_ids.add(aid)
        _fail(errors, not set(arm.get("spaces", [])) <= space_ids, f"arm {aid or '<unknown>'} references an undefined space")
        reranker = arm.get("reranker")
        _fail(errors, reranker not in (None, "") and reranker not in reranker_ids, f"arm {aid or '<unknown>'} references an undefined reranker")
        _fail(errors, not set(arm.get("candidate_depths", depths)) <= set(depths), f"arm {aid or '<unknown>'} has an unconfigured candidate depth")
        if reranker:
            capabilities = next((x.get("capabilities", []) for x in rerankers if x.get("id") == reranker), [])
            modalities_used = {next((x.get("modality") for x in spaces if x.get("id") == sid), None) for sid in arm.get("spaces", [])}
            visual_modalities = {"multimodal", "page_image", "region_image", "mixed"}
            _fail(errors, bool(modalities_used & visual_modalities) and not (visual_modalities & set(capabilities)), f"arm {aid or '<unknown>'} sends visual candidates to an unsupported reranker")

    raw = _canonical(manifest)
    _fail(errors, bool(re.search(r"(?:api[_-]?key|password|secret|authorization)\s*[:=]", raw, re.I)), "credentials/secrets are forbidden")
    _fail(errors, bool(re.search(r"(?:/var/lib/opennicf|/etc/opennicf|production[_-]?data|private[_-]?evidence|raw[_-]?evidence)", raw, re.I)), "production paths or raw private evidence are forbidden")
    if errors:
        raise ManifestValidationError("; ".join(errors))

"""Top-level router for the shared QwenAgent-backed OpenNICF stack."""

from __future__ import annotations

import json
from collections.abc import Mapping, Sequence
from dataclasses import asdict, dataclass, field
from hashlib import sha256
from typing import Any

from .domain_agent import DEFAULT_DOMAIN_IDS, DomainAgentFactory
from .integration_correlation import (
    IntegrationCorrelationAgent,
    IntegrationCorrelationRequest,
)
from .knowledge import KnowledgePlatform
from .model_gateway import ModelGateway, PrivacyPolicy


def _stable_id(prefix: str, *parts: str) -> str:
    digest = sha256()
    digest.update(prefix.encode("utf-8"))
    digest.update(b"\0")
    for part in parts:
        digest.update(part.encode("utf-8"))
        digest.update(b"\0")
    return f"{prefix}_{digest.hexdigest()[:24]}"


def _estimate_tokens(text: str) -> int:
    return max(1, (len(text) + 3) // 4)


def _json_default(value: Any) -> Any:
    if hasattr(value, "__dict__"):
        return asdict(value)
    return str(value)


def _normalize_privacy_policy(value: Any) -> PrivacyPolicy:
    if isinstance(value, PrivacyPolicy):
        return value
    if isinstance(value, bool):
        return PrivacyPolicy.LOCAL_ONLY if value else PrivacyPolicy.LOCAL_PREFERRED
    if value is None:
        return PrivacyPolicy.LOCAL_PREFERRED
    text = str(value).strip()
    if not text:
        return PrivacyPolicy.LOCAL_PREFERRED
    lowered = text.lower()
    if lowered in {"1", "true", "yes", "y", "local", "local_only"}:
        return PrivacyPolicy.LOCAL_ONLY
    if lowered in {"0", "false", "no", "n", "local_preferred", "preferred"}:
        return PrivacyPolicy.LOCAL_PREFERRED
    if lowered == "remote_allowed":
        return PrivacyPolicy.REMOTE_ALLOWED
    if lowered == "remote_required":
        return PrivacyPolicy.REMOTE_REQUIRED
    return PrivacyPolicy(text)


def _normalize_domain_ids(values: Any) -> tuple[str, ...]:
    if values is None:
        return ()
    if isinstance(values, str):
        values = (values,)
    return tuple(str(value).strip() for value in values if str(value).strip())


def _parse_domain_ids(payload: Any) -> tuple[str, ...]:
    if isinstance(payload, Mapping):
        for key in ("domain_ids", "domains", "selected_domain_ids"):
            domain_ids = _normalize_domain_ids(payload.get(key))
            if domain_ids:
                return domain_ids
        return ()
    if isinstance(payload, str):
        candidate = payload.strip()
        if not candidate:
            return ()
        try:
            decoded = json.loads(candidate)
        except json.JSONDecodeError:
            return _normalize_domain_ids(candidate)
        if isinstance(decoded, Mapping):
            for key in ("domain_ids", "domains", "selected_domain_ids"):
                domain_ids = _normalize_domain_ids(decoded.get(key))
                if domain_ids:
                    return domain_ids
        if isinstance(decoded, list):
            return _normalize_domain_ids(decoded)
        if isinstance(decoded, str):
            return _normalize_domain_ids(decoded)
    return ()


def _coerce_model_result(result: Any) -> tuple[str, dict[str, Any]]:
    if isinstance(result, list):
        if result and hasattr(result[0], "content"):
            content = str(result[0].content)
            provider = str(getattr(result[0], "provider", ""))
            return content, {"provider": provider}
        if result and isinstance(result[0], Mapping):
            message = result[0].get("message") or result[0]
            if isinstance(message, Mapping):
                return str(message.get("content") or ""), dict(result[0])
        return "", {"content": result}
    if hasattr(result, "content"):
        metadata = {"provider": getattr(result, "provider", None), "model": getattr(result, "model", None)}
        if getattr(result, "route", None) is not None:
            metadata["route"] = asdict(result.route)
        return str(result.content), {key: value for key, value in metadata.items() if value is not None}
    if isinstance(result, Mapping):
        content = result.get("content")
        if content is not None:
            return str(content), dict(result)
    return str(result), {"content": str(result)}


@dataclass(frozen=True)
class DomainRoutePlan:
    routing_id: str
    question: str
    route_kind: str
    route_source: str
    privacy: str
    local_only: bool
    selected_domain_ids: tuple[str, ...]
    deterministic_domain_ids: tuple[str, ...] = ()
    delegate_domain_id: str | None = None
    classification: dict[str, Any] = field(default_factory=dict)
    correlation: dict[str, Any] = field(default_factory=dict)
    metadata: dict[str, Any] = field(default_factory=dict)
    reason: str = ""
    confidence: float = 0.0

    def to_dict(self) -> dict[str, Any]:
        return {
            "routing_id": self.routing_id,
            "question": self.question,
            "route_kind": self.route_kind,
            "route_source": self.route_source,
            "privacy": self.privacy,
            "local_only": self.local_only,
            "selected_domain_ids": list(self.selected_domain_ids),
            "deterministic_domain_ids": list(self.deterministic_domain_ids),
            "delegate_domain_id": self.delegate_domain_id,
            "classification": self.classification,
            "correlation": self.correlation,
            "metadata": self.metadata,
            "reason": self.reason,
            "confidence": self.confidence,
        }


class DomainRouter:
    """Top-level decision layer for deterministic alias routing and delegation."""

    def __init__(
        self,
        *,
        gateway: ModelGateway | None = None,
        knowledge: KnowledgePlatform | None = None,
        domain_factory: DomainAgentFactory | None = None,
        integration_coordinator: IntegrationCorrelationAgent | None = None,
        coordinator: IntegrationCorrelationAgent | None = None,
        diagnostic_broker: Any | None = None,
        allowed_domain_ids: Sequence[str] | None = None,
        max_domain_fan_out: int = 4,
        max_evidence_budget: int = 16,
        routing_task_class: str = "classification",
        synthesis_task_class: str = "tool_planning",
        privacy: PrivacyPolicy | str = PrivacyPolicy.LOCAL_PREFERRED,
        runtime_factory: Any | None = None,
    ) -> None:
        self.privacy = _normalize_privacy_policy(privacy)
        candidate_coordinator = integration_coordinator or coordinator
        if gateway is None and candidate_coordinator is not None:
            gateway = candidate_coordinator.gateway
        if knowledge is None and candidate_coordinator is not None:
            knowledge = candidate_coordinator.knowledge
        if domain_factory is None and candidate_coordinator is not None:
            domain_factory = candidate_coordinator.domain_factory

        self.gateway = gateway or ModelGateway.from_env()
        self.knowledge = knowledge or KnowledgePlatform.in_memory()
        self.domain_factory = domain_factory or DomainAgentFactory(
            gateway=self.gateway,
            knowledge=self.knowledge,
            diagnostic_broker=diagnostic_broker,
        )
        self.coordinator = candidate_coordinator or IntegrationCorrelationAgent(
            gateway=self.gateway,
            knowledge=self.knowledge,
            domain_factory=self.domain_factory,
            diagnostic_broker=diagnostic_broker,
            allowed_domain_ids=allowed_domain_ids or DEFAULT_DOMAIN_IDS,
            max_domain_fan_out=max_domain_fan_out,
            max_evidence_budget=max_evidence_budget,
            synthesis_task_class=synthesis_task_class,
            privacy=self.privacy,
            runtime_factory=runtime_factory,
        )
        self.routing_task_class = routing_task_class
        self._runtime_factory = runtime_factory
        self.allowed_domain_ids = tuple(allowed_domain_ids or self.coordinator.allowed_domain_ids)

    def _classify(self, request: IntegrationCorrelationRequest) -> dict[str, Any]:
        classification_prompt = {
            "question": request.question or request.raw_request,
            "allowed_domain_ids": list(self.allowed_domain_ids),
            "privacy": request.privacy.value,
            "local_only": request.privacy is PrivacyPolicy.LOCAL_ONLY,
            "time_window": request.time_window,
        }
        messages = [
            {
                "role": "system",
                "content": (
                    "You are the OpenNICF domain router. "
                    "Return JSON with a domain_ids array selecting one or more allowed domains. "
                    "Do not broaden scope beyond the allowed domains."
                ),
            },
            {
                "role": "user",
                "content": json.dumps(classification_prompt, sort_keys=True, default=_json_default),
            },
        ]
        estimated_input_tokens = _estimate_tokens(json.dumps(classification_prompt, sort_keys=True, default=_json_default))
        result = self.gateway.chat(
            messages,
            task_class=self.routing_task_class,
            privacy=request.privacy,
            complex_task=False,
            estimated_input_tokens=estimated_input_tokens,
            source_fan_in=0,
            tool_complexity=0,
            extra_payload={"response_format": {"type": "json_object"}},
        )
        content, metadata = _coerce_model_result(result)
        payload: dict[str, Any]
        try:
            decoded = json.loads(content) if content else {}
            payload = decoded if isinstance(decoded, dict) else {"domain_ids": decoded}
        except json.JSONDecodeError:
            payload = {"content": content}
        payload.setdefault("content", content)
        payload.setdefault("domain_ids", list(_parse_domain_ids(payload)))
        payload["provider"] = metadata.get("provider")
        if "route" in metadata:
            payload["route"] = metadata["route"]
        if "model" in metadata:
            payload["model"] = metadata["model"]
        payload["estimated_input_tokens"] = estimated_input_tokens
        return payload

    def plan(self, request: str | Mapping[str, Any]) -> DomainRoutePlan:
        parsed = IntegrationCorrelationRequest.from_input(request)
        deterministic_domain_ids: tuple[str, ...] = ()
        route_source = "classification"
        classification: dict[str, Any] = {}

        try:
            deterministic_domain_ids = self.coordinator._selected_domain_ids(parsed)
        except ValueError:
            deterministic_domain_ids = ()
        if deterministic_domain_ids:
            selected_domain_ids = deterministic_domain_ids
            route_source = "deterministic_alias"
        else:
            classification = self._classify(parsed)
            selected_domain_ids = _parse_domain_ids(classification)
            if not selected_domain_ids:
                raise ValueError("domain routing classification did not return any domain ids")
            route_source = "classification"

        route_kind = "single_domain" if len(selected_domain_ids) == 1 else "integration_correlation"
        delegate_domain_id = selected_domain_ids[0] if route_kind == "single_domain" else "integration_correlation"
        correlation: dict[str, Any] = {}
        if route_kind == "integration_correlation":
            correlation = {
                "selected_domain_ids": list(selected_domain_ids),
                "selected_domain_count": len(selected_domain_ids),
            }
        routing_id = _stable_id(
            "route",
            parsed.question or parsed.raw_request,
            route_kind,
            route_source,
            self.privacy.value,
            ",".join(selected_domain_ids),
        )
        return DomainRoutePlan(
            routing_id=routing_id,
            question=parsed.question or parsed.raw_request,
            route_kind=route_kind,
            route_source=route_source,
            privacy=parsed.privacy.value,
            local_only=parsed.privacy is PrivacyPolicy.LOCAL_ONLY,

